  "additionalProperties": false,
  "properties": {
    "curb65": {
      "maximum": 5,
      "minimum": 0,
      "title": "Curb65",
      "type": "integer"
    },
    "curb65_criteria_met": {
      "items": {
        "type": "string"
      },
      "title": "Curb65 Criteria Met",
      "type": "array"
