{
  "assessment": "Severe community-acquired pneumonia (CURB-65 score 3, ATS/IDSA criteria met) with Gram-negative rods on sputum Gram stain, requiring high-dependency unit admission.",
  "regimen": [
    {
      "drug": "ceftriaxone",
      "dose": "2 g",
      "route": "intravenous",
      "frequency": "every 24 hours"
    },
    {
      "drug": "azithromycin",
      "dose": "500 mg",
      "route": "intravenous",
      "frequency": "every 24 hours"
    }
  ],
  "rationale": "The 2019 ATS/IDSA guidelines recommend combination therapy with a beta-lactam (e.g., ceftriaxone) plus a macrolide (e.g., azithromycin) for empiric treatment of severe community-acquired pneumonia in adults. This regimen covers typical bacterial pathogens (e.g., Streptococcus pneumoniae) and atypical pathogens (e.g., Legionella, Mycoplasma). The presence of Gram-negative rods on sputum Gram stain suggests possible Haemophilus influenzae or Klebsiella pneumoniae, which are also covered by ceftriaxone. The patient has no risk factors for Pseudomonas or MRSA, so broader coverage is not indicated. Intravenous therapy is appropriate given the severity of illness and high-dependency unit admission.",
  "confidence": "very high"
}
```

