{
  "assessment": "Severe community-acquired pneumonia (CAP) in a 52-year-old man with no known drug allergies, meeting ATS/IDSA criteria for severe CAP (1 major and 3 minor criteria). Sputum Gram stain shows Gram-negative rods, raising concern for possible atypical or Gram-negative pathogens, though typical CAP pathogens (e.g., *Streptococcus pneumoniae*) remain most likely.",
  "regimen": [
    {
      "drug": "ceftriaxone",
      "dose": "2 g",
      "route": "IV",
      "frequency": "every 24 hours"
    },
    {
      "drug": "azithromycin",
      "dose": "500 mg",
      "route": "IV",
      "frequency": "every 24 hours"
    }
  ],
